1	// The printer panel's own parts: the card pinned above the thread, the cards
2	// drawn inside it, the row of things to tap, and the card that confirms a
3	// change to a printer.
4	//
5	// Everything here renders host state, in words made on this page
6	// (printerWords.ts). A tap sends a typed printer action or a tool decision,
7	// which C++ carries out -- never a change made on this side, and never words
8	// sent as the person's. A tap the model should know about carries its note,
9	// which the app records if the tap goes through.
10	
11	import { memo } from 'react';
12	import type {
13	  NetworkPrinterInfo,
14	  PrinterBlock,
15	  PrinterCardInfo,
16	  PrinterChangeConfirm,
17	  PrinterSessionPayload,
18	  PrinterSpoolInfo,
19	  ToolActivityInfo,
20	} from '../bridge/protocol';
21	import {
22	  ADD_LABEL,
23	  REJECT_LABEL,
24	  caption,
25	  cardSubline,
26	  changeTitle,
27	  chosenNote,
28	  factTexts,
29	  mm,
