244	// A change the model worked out from what the person said, stated in words
245	// before anything is saved: the card is where a misreading is caught.
246	export function PrinterChangeCard({
247	  activity,
248	  onDecision,
249	}: {
250	  activity: ToolActivityInfo;
251	  onDecision: (actionId: string, decision: 'approve' | 'reject') => void;
252	}) {
253	  const args = activity.arguments as { nozzle?: number; spools?: PrinterSpoolInfo[]; confirm?: PrinterChangeConfirm };
254	  const confirm = args.confirm;
255	  const printer = confirm?.printer ?? 'this printer';
256	  const nozzle = args.nozzle !== undefined && confirm?.before.nozzle !== undefined;
257	  const spools = args.spools !== undefined && confirm?.before.spools !== undefined;
258	  const keep = nozzle && !spools ? `Keep ${mm(confirm!.before.nozzle!)}` : 'Keep as it is';
259	  const set = nozzle && !spools ? `Set ${mm(args.nozzle!)}` : spools && !nozzle ? 'Set these spools' : 'Set both';
260	
261	  return (
262	    <div className={`printer-change state-${activity.state}`} data-testid={`tool-${activity.actionId}`}>
263	      <div className="printer-change-title">{changeTitle(nozzle, spools)}</div>
264	      {nozzle && (
265	        <>
266	          <div className="printer-change-line">
267	            {mm(confirm!.before.nozzle!)} → <b>{mm(args.nozzle!)}</b> on {printer}
268	          </div>
269	          <div className="printer-change-note">Every project that uses this printer slices for {mm(args.nozzle!)}.</div>
270	        </>
271	      )}
272	      {spools && (
273	        <div className="printer-change-line printer-change-spool-diff">
274	          <div>
275	            <small>Now on {printer}</small>
276	            <SpoolList spools={confirm!.before.spools!} />
277	          </div>
278	          <span aria-hidden="true">→</span>
279	          <div>
280	            <small>After</small>
281	            <SpoolList spools={args.spools!} />
282	          </div>
283	        </div>
284	      )}
285	      {activity.state === 'pending' && (
286	        <div className="printer-change-actions">
287	          <button type="button" className="printer-chip printer-chip-plain" onClick={() => onDecision(activity.actionId, 'reject')}>
288	            {keep}
289	          </button>
290	          <button
291	            type="button"
292	            className="printer-chip printer-chip-primary"
293	            onClick={() => onDecision(activity.actionId, 'approve')}
294	          >
295	            {set}
296	          </button>
297	        </div>
298	      )}
299	      {activity.state === 'rejected' && <div className="printer-change-state">Kept as it was</div>}
300	      {(activity.state === 'approved' || activity.state === 'running') && <div className="printer-change-state">Saving…</div>}
301	      {activity.state === 'failed' && <div className="tool-error">{activity.error?.message ?? 'The change was not saved.'}</div>}
302	    </div>
303	  );
304	}
