128	// -- What the model is told after a tap ---------------------------------------
129	// Statements of what the person did, never instructions. The app posts them
130	// only when the tap goes through as described.
131	
132	export function rejectedNote(name: string): string {
133	  return `The person said ${name} is not their printer.`;
134	}
135	
136	export function chosenNote(card: PrinterCardInfo): string {
137	  const assumed = [`a ${mm(card.assumed.nozzle)} nozzle`];
138	  if (card.assumed.plate) assumed.push(`the ${card.assumed.plate}`);
139	  if (card.assumed.filament) assumed.push(card.assumed.filament);
140	  let text = `The person chose ${card.name}. Its card offers Add, assuming ${listed(assumed)}`;
141	  if (!card.assumed.plate) text += '; the profile names no plate';
142	  if (!card.assumed.filament) text += '; the profile names no filament';
143	  return `${text}.`;
144	}
145	
146	// For a network printer the app matched to a model in the list.
147	export function networkNote(printer: NetworkPrinterInfo): string {
148	  const match = printer.match;
149	  if (!match) return '';
150	  const start = `The person chose the network printer ${printer.serial}, a ${match.name}`;
151	  return match.reported
152	    ? `${start} that reports a ${mm(match.nozzle)} nozzle.`
153	    : `${start}; it did not report its nozzle, so its card assumes ${mm(match.nozzle)}.`;
154	}
155	
156	export function undoneNote(block: PrinterBlock): string {
157	  const back: string[] = [];
158	  if (block.changed?.nozzle) back.push(`the nozzle is ${mm(block.changed.nozzle.before)} again`);
159	  if (block.changed?.spools) back.push(`the spools are ${spoolsText(block.changed.spools.before)} again`);
160	  return `The person undid the change: ${listed(back)}.`;
161	}
