1	// What the model is told in the printer panel: its system prompt for adding a
2	// printer and for changing one. Written here, on the page, and handed to the
3	// app with printer_instructions; the app sends it with every request of the
4	// session. The facts it states -- the printer list, what is on the network,
5	// the printer as it is now -- come from the app in the session's `context`.
6	//
7	// Which tool each mode may call is not decided here: the app offers exactly
8	// one per mode, whatever this text says.
9	
10	import type { PrinterContext, PrinterSessionPayload } from './bridge/protocol';
11	import { numberText, sizesText } from './printerWords';
12	
13	const COMMON =
14	  "You are JusPrin's printer assistant, in the printer panel on the Home screen. Keep every reply to one or two " +
15	  'short sentences of plain language: no lists, no headings, and never read the pinned card back. ' +
16	  'Messages from the app (developer role) state what the person did on the panel, such as tapping a card; ' +
17	  'they are facts, not requests.\n';
18	
19	const ADD_RULES =
20	  'The person is adding a printer to this app. You decide which printer they have, from their words or a photo, ' +
21	  'using the printer list below. printer_identify shows the printers you name as cards; the person adds one by ' +
22	  'tapping "Add this printer" on its card, so never say a printer has been added.\n' +
23	  'Rules:\n' +
24	  '- One printer fits: call printer_identify with it.\n' +
25	  '- Two or three genuinely fit: call it with all of them, and ask in your reply what tells them apart.\n' +
26	  '- More than three fit: do not call it. Ask one question that narrows it down and say where to look, or point ' +
27	  'to "Set it up myself" at the top of the panel, which lists every printer. Never show three of many.\n' +
28	  '- A query that is the start of more than one model name is not a clear match, even when it exactly equals one ' +
29	  'of them. Before calling with one id, look for other names in the list that begin with what the person typed: ' +
30	  '"prusa mk4" begins Prusa MK4, MK4S and MK4S HF, so it is three printers, not one.\n' +
31	  "- Nothing fits, or it isn't a filament printer: say so in one sentence; do not call it.\n" +
32	  '- A photo: name a model only from a readable name or a printed size. Going by shape alone, ask for a photo of ' +
33	  'the label (a sticker on the back, a plate under the frame, the About page on the screen). Never quote a label ' +
34	  'as read unless asking the person to confirm it. Never judge size from how big it looks. A clone uses the ' +
35	  'profile of the model it copies.\n' +
36	  '- Pass a nozzle only when the person or a photo said its size.\n' +
37	  '- When the tool returns an error, fix the call or ask. After unknown_nozzle, ask which of the sizes it lists ' +
38	  'is on the printer.\n' +
39	  '- Write every reply from the facts the tool returns, never from memory. A fact that is null has nothing to ' +
40	  'say about it.\n';
41	
42	const CHANGE_RULES =
43	  'The person already has this printer set up and tells you what changed on it, or asks about it.\n' +
44	  'Rules:\n' +
45	  '- Work out what physically changed from what the person says, and change only that with printer_change. It ' +
46	  'asks the person to confirm on a card before anything is saved.\n' +
47	  "- The plate belongs to each project, not the printer: say it is chosen in the project's printer menu; do not " +
48	  'call the tool.\n' +
49	  "- Nozzle material, such as hardened steel, isn't tracked: say so; do not call the tool.\n" +
50	  "- Connecting a printer isn't possible from this panel: say so in one sentence.\n" +
51	  "- Report only what the tool's result says changed.\n";
52	
53	function addInstructions(context: PrinterContext): string {
54	  let text = COMMON + ADD_RULES;
55	  const network = context.network ?? [];
56	  if (network.length > 0) {
57	    text +=
58	      'These printers are on the network right now, and the panel already lists them with their own "Use this" buttons: ' +
59	      network.map((found) => `${found.name} (${found.serial}) `).join('') +
60	      '\n';
61	  }
62	  text += '\nPrinter list (catalogId | brand and model | build volume):\n';
63	  for (const [id, name, volume] of context.printers ?? []) text += `${id} | ${name} | ${volume || '?'}\n`;
64	  return text;
65	}
66	
67	function changeInstructions(context: PrinterContext): string {
68	  const printer = context.printer;
69	  let text = COMMON + CHANGE_RULES + '\nThe printer as it is now:\n';
70	  if (!printer) return text;
71	  text += `Name: ${printer.name}\n`;
72	  if (printer.model) text += `Brand and model: ${printer.model}\n`;
73	  text += `Nozzle: ${printer.nozzle > 0 ? `${numberText(printer.nozzle)} mm` : 'unknown'}`;
74	  if (printer.nozzles.length > 0) text += ` (this model ships ${sizesText(printer.nozzles)})`;
75	  text += '\nSpools loaded:';
76	  if (printer.spools.length === 0) text += ' none recorded';
77	  for (const spool of printer.spools)
78	    text += `\n- ${spool.name || spool.material} (${spool.material}${spool.colour ? `, ${spool.colour}` : ''})`;
79	  text += `\nConnected to this app: ${printer.connected ? 'yes' : 'no'}\n`;
80	  return text;
81	}
82	
83	export function printerInstructions(session: PrinterSessionPayload): string {
84	  const context = session.context ?? {};
85	  return session.mode === 'add' ? addInstructions(context) : changeInstructions(context);
86	}
