1	// Composer input rules from the handoff: Enter sends, Shift+Enter inserts a
2	// newline, and Enter during IME composition accepts the composition without
3	// sending. Normal selection, clipboard, and focus behavior are left to the
4	// browser engine. The in-progress draft is reported (debounced) so the host
5	// can keep it in the local recovery store; reconnecting restores it via
6	// initialText.
7	//
8	// Attachments enter through a file picker, drag-and-drop, or pasting an image;
9	// staged attachments render as removable chips, and a message may be sent with
10	// attachments and no text. The host owns decoding and storage — the composer
11	// only hands it files.
12	
13	import { ChangeEvent, ClipboardEvent, DragEvent, KeyboardEvent, useEffect, useRef, useState } from 'react';
14	import { AttachmentInfo, AttachmentSource } from '../bridge/protocol';
15	import { AttachmentChip } from './AttachmentChip';
16	import { CameraGlyph } from './PrinterPanel';
17	
18	interface Props {
19	  disabled: boolean;
20	  disabledReason?: string;
21	  streaming: boolean;
22	  initialText?: string;
23	  attachments: AttachmentInfo[]; // staged attachments only
24	  onSend: (text: string) => void;
25	  onStop: () => void;
26	  onAttachFiles: (files: File[], source: AttachmentSource) => void;
27	  onRemoveAttachment: (id: string) => void;
28	  onDraftChange?: (text: string) => void;
29	  draftDebounceMs?: number;
30	  // Fired on the keystroke itself, not on the debounced draft save. Anything
31	  // covering the thread uses this to get out of the way immediately.
32	  onTyping?: () => void;
33	  // A likely answer to what was just asked, rather than the standing
34	  // invitation. The printer panel writes one per turn.
35	  placeholder?: string;
36	  // Labelled "Photo" instead of a bare paperclip: in the printer panel a
37	  // picture is a primary way to say which printer this is, not an extra.
38	  photoButton?: boolean;
39	}
40	
