42	// inline rather than masked from resources/jusprin/ui/icons because that icon
43	// set has no arrow yet; `currentColor` keeps it on the button's text token.
44	function SendGlyph() {
45	  return (
46	    <svg className="send-glyph" viewBox="0 0 16 16" aria-hidden="true" focusable="false">
47	      <path
48	        d="M8 13V3.5M8 3.5 3.75 7.75M8 3.5 12.25 7.75"
49	        fill="none"
50	        stroke="currentColor"
51	        strokeWidth="1.75"
52	        strokeLinecap="round"
53	        strokeLinejoin="round"
54	      />
