59	export function Composer({
60	  disabled,
61	  disabledReason,
62	  streaming,
63	  initialText,
64	  attachments,
65	  onSend,
66	  onStop,
67	  onAttachFiles,
68	  onRemoveAttachment,
69	  onDraftChange,
70	  draftDebounceMs = 300,
71	  onTyping,
72	  placeholder,
73	  photoButton,
74	}: Props) {
75	  const [text, setText] = useState(initialText ?? '');
76	  const [dragging, setDragging] = useState(false);
77	  const draftTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
78	  const fileInput = useRef<HTMLInputElement>(null);
79	
80	  // A recovered draft arrives after the first connect; apply it only while
81	  // the composer is untouched so it never clobbers active typing.
82	  const touched = useRef(false);
83	  useEffect(() => {
84	    if (!touched.current && initialText) setText(initialText);
85	    // eslint-disable-next-line react-hooks/exhaustive-deps
86	  }, [initialText]);
87	
88	  useEffect(() => {
89	    return () => {
90	      if (draftTimer.current !== null) clearTimeout(draftTimer.current);
91	    };
92	  }, []);
93	
94	  const reportDraft = (value: string) => {
95	    if (!onDraftChange) return;
96	    if (draftTimer.current !== null) clearTimeout(draftTimer.current);
97	    draftTimer.current = setTimeout(() => onDraftChange(value), draftDebounceMs);
98	  };
99	
100	  const hasSendable = attachments.some((a) => a.state === 'staged');
101	  const canSend = (!!text.trim() || hasSendable) && !disabled && !streaming;
102	
103	  const send = () => {
104	    if (!canSend) return;
105	    if (draftTimer.current !== null) clearTimeout(draftTimer.current);
106	    onSend(text.trim());
107	    setText('');
108	  };
109	
110	  const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
111	    if (event.key !== 'Enter' || event.shiftKey) return;
112	    // 229 is the legacy IME-processing keyCode some engines still report.
113	    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
114	    event.preventDefault();
115	    send();
116	  };
117	
118	  const handleFiles = (files: FileList | null, source: AttachmentSource) => {
119	    if (!files || files.length === 0) return;
120	    onAttachFiles(Array.from(files), source);
121	  };
122	
123	  const handlePickerChange = (event: ChangeEvent<HTMLInputElement>) => {
124	    handleFiles(event.target.files, 'picker');
125	    event.target.value = ''; // allow re-picking the same file
126	  };
127	
128	  const handlePaste = (event: ClipboardEvent<HTMLTextAreaElement>) => {
129	    const files = Array.from(event.clipboardData.files ?? []);
130	    if (files.length > 0) {
131	      event.preventDefault();
132	      onAttachFiles(files, 'clipboard');
133	    }
134	  };
135	
136	  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
137	    event.preventDefault();
138	    setDragging(false);
139	    if (disabled) return;
140	    handleFiles(event.dataTransfer.files, 'drop');
141	  };
142	
143	  return (
144	    <div
145	      className={`composer${dragging ? ' dragging' : ''}`}
146	      onDragOver={(event) => {
147	        event.preventDefault();
148	        if (!disabled) setDragging(true);
149	      }}
150	      onDragLeave={() => setDragging(false)}
151	      onDrop={handleDrop}
152	    >
153	      {attachments.length > 0 && (
154	        <div className="composer-attachments" aria-label="Staged attachments">
155	          {attachments.map((attachment) => (
156	            <AttachmentChip key={attachment.id} attachment={attachment} onRemove={onRemoveAttachment} />
157	          ))}
158	          {/* A staged photo waits for the person; it never sends itself. */}
159	          {photoButton && <span className="composer-staged-hint">add a note, or just send</span>}
160	        </div>
161	      )}
162	      <div className="composer-row">
163	        <button
164	          type="button"
165	          className={photoButton ? 'attach-button attach-button-photo' : 'attach-button'}
166	          aria-label={photoButton ? 'Add a photo' : 'Attach a file'}
167	          disabled={disabled}
168	          onClick={() => fileInput.current?.click()}
169	        >
170	          {photoButton ? <CameraGlyph className="photo-glyph" /> : <span className="attach-glyph" aria-hidden="true" />}
171	          {photoButton && 'Photo'}
172	        </button>
173	        <input
174	          ref={fileInput}
175	          type="file"
176	          multiple
177	          className="attach-input"
178	          aria-hidden="true"
179	          tabIndex={-1}
180	          style={{ display: 'none' }}
181	          onChange={handlePickerChange}
182	        />
183	        <textarea
184	          aria-label="Message the Agent"
185	          placeholder={
186	            disabled
187	              ? disabledReason ?? 'The Agent is not available'
188	              : placeholder ?? 'Ask about this print or request a change…'
189	          }
190	          value={text}
191	          disabled={disabled}
192	          onChange={(event) => {
193	            touched.current = true;
194	            onTyping?.();
195	            setText(event.target.value);
196	            reportDraft(event.target.value);
197	          }}
198	          onKeyDown={handleKeyDown}
199	          onPaste={handlePaste}
200	          rows={2}
201	        />
202	        {streaming ? (
203	          <button type="button" className="composer-send" onClick={onStop} aria-label="Stop generating">
204	            <span className="stop-glyph" aria-hidden="true" />
205	          </button>
206	        ) : (
207	          <button
208	            type="button"
209	            className="composer-send"
210	            onClick={send}
211	            disabled={!canSend}
212	            aria-label="Send message"
213	          >
214	            <SendGlyph />
215	          </button>
216	        )}
217	      </div>
218	    </div>
219	  );
220	}
