#pragma once

// The data behind the Home page, and the one function that turns it into the
// `state` payload of the jusprin-home-bridge protocol. No wx and no Orca types
// appear here, so the payload's shape is testable without a GUI: everything
// that needs a MainFrame, a PresetBundle, or the device layer lives in
// HomeHost, which fills these structs and hands them over.
//
// Optional fields are omitted from the JSON rather than sent as null or as an
// empty string: the page distinguishes "the host has nothing to say" from "the
// host says it is empty", and a serialised null would read as the latter.

#include <nlohmann/json_fwd.hpp>

#include <string>
#include <vector>

namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {

// Matches ProjectStatusKind in the page's protocol.ts. 'unknown' is what the
// host sends while nothing in the codebase records per-project slice state:
// the text carries what can be derived instead, and only 'printing' earns a
// colored dot on the card.
enum class ProjectStatusKind { Unknown, Draft, Sliced, Printing, Completed };

const char* to_string(ProjectStatusKind kind);

struct ProjectEntry
{
    std::string        id;
    std::string        name;
    std::string        path;
    std::string        thumbnail_url; // empty when the .3mf carries none
    ProjectStatusKind  status_kind{ProjectStatusKind::Unknown};
    std::string        status_text;
};

struct SpoolEntry
{
    std::string colour; // '#RRGGBB'
};

enum class PrinterState { Idle, Printing, Offline };

const char* to_string(PrinterState state);

// What a card stands for, which decides how the page asks about its actions.
// A named printer is one the person added and names in JusPrin; the page
// confirms a rename or removal itself. A device is a Bambu printer on the
// network or the account that no named printer stands for; its rename and
// removal are Orca's own dialogs, which confirm for themselves.
enum class PrinterKind { Named, Device };

const char* to_string(PrinterKind kind);

struct PrinterEntry
{
    std::string             id;
    std::string             name;
    PrinterKind             kind{PrinterKind::Named};
    // The card's menu. An action the card cannot offer is sent as false and
    // shown disabled, so the menu keeps its shape.
    bool                    can_open_settings{false};
    bool                    can_rename{false};
    bool                    can_remove{false};
    PrinterState            state{PrinterState::Idle};
    std::string             status_text;
    // Below zero whenever there is no job to report; only a printing printer
    // sends a bar.
    int                     progress_percent{-1};
    std::string             connection_text;
    std::string             nozzle_text;
    std::string             material_label;
    std::vector<SpoolEntry> spools;
    bool                    can_launch_monitor{false};
};

struct Snapshot
{
    bool                      dark{false};
    std::vector<ProjectEntry> projects;
    std::vector<PrinterEntry> printers;
    // The printer conversation has the printers column, so the page leaves
    // that place to it.
    bool                      printer_panel_open{false};
};

// The `state` payload: { appearance, projects, printers, printerPanelOpen }.
nlohmann::json state_payload(const Snapshot& snapshot);

#pragma once

// The printer conversation, in place of Home's printers column.
//
// It is the Prepare screen's panel in shape -- the same page, thread and
// composer -- with a printer session behind it instead of the project's: its
// own AgentHost, its own agent service, and an in-memory document, so nothing
// said here is written to the open project. Every opening is a new session,
// so the whole runtime is built when the panel opens and torn down when it
// closes.

#include "PrinterConversation.hpp"
#include "slic3r/GUI/JusPrin/Agent/AgentWebView.hpp"
#include "slic3r/GUI/JusPrin/Shell/ShellTheme.hpp"

#include <wx/panel.h>
#include <wx/timer.h>

#include <functional>
#include <memory>
#include <string>
#include <vector>

namespace Slic3r::GUI { class Plater; }
namespace Slic3r::GUI::JusPrin::Workspace { class SpoolStore; }

namespace Slic3r::GUI::JusPrin::PrinterSetup {

class PrinterPanel : public wxPanel, private IConversationHost
{
public:
    struct Callbacks
    {
        // "‹ Printers", and everything else that ends the session.
        std::function<void()> closed;
        // A printer was saved or changed; Home's list is out of date.
        std::function<void()> printers_changed;
        // The person set the agent up in here, so the rest of the shell has
        // to look again at how it is configured.
        std::function<void()> agent_configured;
    };

    PrinterPanel(wxWindow*              parent,
                 const ShellTheme&      theme,
                 bool                   dark,
                 Workspace::IWorkspace& workspace,
                 Plater&                plater,
                 Workspace::SpoolStore* spools,
                 Callbacks              callbacks);
    ~PrinterPanel() override;

// Adopt the currently open project once the host has registered its
// listeners, so the initial document reaches the pane too.
m_persistence->attach();

// One shell-owned pump continues throughout WebView page reloads.
// The page handshake gates delivery, not native MCP execution.
m_runtime_timer.Start(33);

// Home is a fork-owned panel beside the Notebook, not one of its pages.
// The Notebook keeps every page it had, so upstream keeps the meaning
// of its indices: the dialog parents that ask for page 0, the
// predicates that key off GetSelection(), and any future cast of a
// page all still find the window they expect. The shell owns only
// which of the two is on screen for tpHome.
m_home = new Home::HomeWebView(&frame, *m_theme, frame, m_status_row->spool_store());
