1	// Home's state and the one reducer that advances it. The page renders what the
2	// host last said; it owns no project or printer state of its own, so a reload
3	// is always recoverable from the next `state` envelope.
4	
5	import type { ConnectionState } from '../bridge/client';
6	import type {
7	  Appearance,
8	  Envelope,
9	  PrinterErrorPayload,
10	  PrinterInfo,
11	  ProjectInfo,
12	  StatePayload,
13	} from '../bridge/protocol';
14	
15	export interface HomeState {
16	  connection: ConnectionState;
17	  connectionDetail?: string;
18	  // Absent until the host answers the handshake with state: an empty gallery
19	  // and "no projects yet" are different screens.
20	  loaded: boolean;
21	  appearance: Appearance;
22	  projects: ProjectInfo[];
23	  printers: PrinterInfo[];
24	  // The printer conversation is open in place of the printers column.
25	  printerPanelOpen: boolean;
26	  error?: string;
27	  // The last printer action the host refused. The host follows a refusal with
28	  // a fresh state, so only the person's next printer action clears it.
29	  printerError?: PrinterErrorPayload;
30	}
31	
32	export const initialState: HomeState = {
33	  connection: 'connecting',
34	  loaded: false,
35	  appearance: 'light',
36	  projects: [],
37	  printers: [],
38	  printerPanelOpen: false,
39	};
40	
41	export type HomeAction =
42	  | { kind: 'connection'; state: ConnectionState; detail?: string }
43	  | { kind: 'envelope'; envelope: Envelope }
44	  | { kind: 'printer_action' };
45	
46	export function reduce(state: HomeState, action: HomeAction): HomeState {
47	  if (action.kind === 'connection') {
48	    return { ...state, connection: action.state, connectionDetail: action.detail };
49	  }
50	  if (action.kind === 'printer_action') {
51	    return { ...state, printerError: undefined };
52	  }
53	  const { type, payload } = action.envelope;
54	  switch (type) {
55	    case 'state': {
56	      const next = payload as StatePayload;
57	      return {
58	        ...state,
59	        loaded: true,
60	        appearance: next.appearance,
61	        projects: next.projects ?? [],
62	        printers: next.printers ?? [],
63	        printerPanelOpen: next.printerPanelOpen ?? false,
64	        error: undefined,
65	      };
66	    }
67	    case 'projects':
68	      return { ...state, projects: (payload as { projects: ProjectInfo[] }).projects ?? [] };
69	    case 'printers':
70	      return { ...state, printers: (payload as { printers: PrinterInfo[] }).printers ?? [] };
71	    case 'appearance':
72	      return { ...state, appearance: (payload as { appearance: Appearance }).appearance };
73	    case 'printer_panel':
74	      return { ...state, printerPanelOpen: (payload as { open: boolean }).open };
75	    case 'printer_error':
76	      return { ...state, printerError: payload as PrinterErrorPayload };
77	    case 'bridge_error':
78	      return { ...state, error: (payload as { message?: string }).message };
79	    default:
80	      return state;
81	  }
82	}
